begin;
select no_plan();
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111401','transfer-a@example.invalid'),('11111111-1111-4111-8111-111111111402','transfer-b@example.invalid');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111401',true);
create temp table transfer_fixtures(kind text primary key,result jsonb);
create temp table transfer_nutrients as select jsonb_agg(jsonb_build_object('code',code,'unit',unit,'amount',case code when 'energy' then 400 when 'protein' then 20 when 'fat' then 10 when 'carbohydrate' then 200 when 'fiber' then 20 when 'carbohydrate_excluding_fiber' then 180 when 'salt_equivalent' then 1 when 'copper' then 0 when 'molybdenum' then null else 100 end,'provenance','user_entered','quality','unverified','value_origin','user_reported')) nutrients from public.nutrient_definitions;
insert into transfer_fixtures select 'catalog',public.create_catalog_item_v3(gen_random_uuid(),2,now(),'ingredient','転送用食品',null,100,'g',(select nutrients from transfer_nutrients));
create temp table transfer_request as select jsonb_build_object('source_kind','catalog','source_id',(select result->>'item_id' from transfer_fixtures where kind='catalog'),'mode','basic7','quantity','50','quantity_unit','g') request;
select is(jsonb_array_length(public.get_karomiru_source_v1((select request from transfer_request))->'nutrients'),29,'sharing payload contains 29 standard rows');
select is((select r->>'amount_numerator' from jsonb_array_elements(public.get_karomiru_source_v1((select request from transfer_request))->'nutrients') r where r->>'code'='protein'),'1000.000000','catalog numerator retains exact multiplication');
select is((select (r->>'amount_denominator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request from transfer_request))->'nutrients') r where r->>'code'='protein'),100::numeric,'catalog denominator records original serving basis');
select is((select count(*)::integer from jsonb_array_elements(public.get_karomiru_source_v1((select request from transfer_request))->'nutrients') r where r->>'code'='sodium'),0,'internal sodium excluded');
select ok((select r->'amount_numerator'='null'::jsonb from jsonb_array_elements(public.get_karomiru_source_v1((select request from transfer_request))->'nutrients') r where r->>'code'='molybdenum'),'unknown is null, never zero');
select is((select (r->>'amount_numerator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request from transfer_request))->'nutrients') r where r->>'code'='copper'),0::numeric,'explicit zero remains known');
select throws_ok($$select public.get_karomiru_source_v1((select request||'{"quantity_unit":"ml"}' from transfer_request))$$,'PT422','quantity_unit_mismatch','no arbitrary g/ml conversion');
insert into transfer_fixtures select 'prepared',public.prepare_karomiru_transfer_v1('30000000-0000-4000-8000-000000001401',2,now(),(select request from transfer_request));
create temp table fixed_transfer as select fixed_payload,payload_hash from public.karomiru_transfers where id='30000000-0000-4000-8000-000000001401';
select is(public.get_karomiru_transfer_v1('30000000-0000-4000-8000-000000001401')->>'status','prepared','preparing/reading an image never confirms external registration');
select is(public.get_karomiru_transfer_v1('30000000-0000-4000-8000-000000001401')->>'current_source_changed','false','initial source matches fixed payload');
select is(public.prepare_karomiru_transfer_v1('30000000-0000-4000-8000-000000001401',2,now(),(select request from transfer_request)),(select result from transfer_fixtures where kind='prepared'),'prepare retry reuses fixed transfer instead of duplicate');
insert into transfer_fixtures select 'entry',public.create_meal_entry_v3(gen_random_uuid(),2,now(),(now() at time zone 'Asia/Tokyo')::date,'breakfast',now(),(select (result->>'item_id')::uuid from transfer_fixtures where kind='catalog'),50,'g',(public.get_catalog_reference_fingerprint_v3((select (result->>'item_id')::uuid from transfer_fixtures where kind='catalog'))->>'reference_fingerprint'));
create temp table entry_request as select jsonb_build_object('source_kind','entry','source_id',(select result->>'entry_id' from transfer_fixtures where kind='entry'),'mode','all29') request;
select is((select (r->>'amount_numerator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request from entry_request))->'nutrients') r where r->>'code'='protein'),10::numeric,'snapshot already scaled to 50g is not multiplied again');
select is((select (r->>'amount_denominator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request from entry_request))->'nutrients') r where r->>'code'='protein'),1::numeric,'entry denominator is one');
select throws_ok($$select public.get_karomiru_source_v1((select request||'{"quantity":"2"}' from entry_request))$$,'PT422','snapshot_must_not_be_rescaled','entry rescaling is explicitly rejected');
insert into transfer_fixtures select 'entry_transfer',public.prepare_karomiru_transfer_v1(gen_random_uuid(),2,now(),(select request from entry_request));
create temp table before_transfer_snapshots as select jsonb_agg(to_jsonb(s) order by s.meal_entry_id,s.nutrient_code) data from public.meal_entry_nutrient_snapshots s join public.meal_entries e on e.id=s.meal_entry_id where e.user_id=auth.uid();
insert into transfer_fixtures select 'sparse',public.create_catalog_item_v3(gen_random_uuid(),2,now(),'ingredient','部分値の食品',null,1,'個','[{"code":"energy","amount":100,"unit":"kcal","provenance":"user_entered","quality":"unverified"},{"code":"fat","amount":0,"unit":"g","provenance":"user_entered","quality":"unverified"}]');
select public.create_meal_entry_v3(gen_random_uuid(),2,now(),(now() at time zone 'Asia/Tokyo')::date,'breakfast',now(),(select (result->>'item_id')::uuid from transfer_fixtures where kind='sparse'),1,'個',(public.get_catalog_reference_fingerprint_v3((select (result->>'item_id')::uuid from transfer_fixtures where kind='sparse'))->>'reference_fingerprint'));
create temp table whole_request as select jsonb_build_object('source_kind','meal','source_id',(select result->>'meal_id' from transfer_fixtures where kind='entry'),'mode','all29') request;
select ok((select r->'amount_numerator'='null'::jsonb and r->>'state'='partial' and (r->>'known_source_amount')::numeric=10 from jsonb_array_elements(public.get_karomiru_source_v1((select request from whole_request))->'nutrients') r where r->>'code'='protein'),'whole meal with an unknown ingredient does not promote known subtotal into a complete amount');
select is((select (r->>'amount_numerator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request from whole_request))->'nutrients') r where r->>'code'='energy'),300::numeric,'whole meal sums stored amounts once');
insert into transfer_fixtures select 'batch',to_jsonb(public.create_batch('作り置き転送',null,4,'食',jsonb_build_array(jsonb_build_object('catalog_item_id',(select result->>'item_id' from transfer_fixtures where kind='catalog'),'quantity',200,'quantity_unit','g')),'transfer-batch-fixture'));
create temp table batch_request as select jsonb_build_object('source_kind','batch','source_id',(select result->>'id' from transfer_fixtures where kind='batch'),'mode','all29','batch_scope','one') request;
select is((select (r->>'amount_numerator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request from batch_request))->'nutrients') r where r->>'code'='protein'),10::numeric,'batch one portion is a quarter of its recipe total');
select is((select (r->>'amount_numerator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request||'{"batch_scope":"all"}' from batch_request))->'nutrients') r where r->>'code'='protein'),40::numeric,'batch all portions uses stored serving count');
insert into transfer_fixtures select 'product',public.create_product_item_reliable_v3(gen_random_uuid(),2,now(),'product','4901234567894','転送用Product',null,100,'g',null,null,null,'user_entered','user',null,now(),(select nutrients from transfer_nutrients));
select is(jsonb_array_length(public.get_karomiru_source_v1(jsonb_build_object('source_kind','product','source_id',(select result->>'item_id' from transfer_fixtures where kind='product')))->'nutrients'),29,'Product source exposes the complete standard registry');
select public.update_catalog_item_v3(gen_random_uuid(),2,now(),(select (result->>'item_id')::uuid from transfer_fixtures where kind='catalog'),1,'転送用食品',null,100,'g',true,(select jsonb_agg(n||case when n->>'code'='protein' then '{"amount":30}'::jsonb else '{}'::jsonb end) from transfer_nutrients,jsonb_array_elements(nutrients)n));
select is(public.get_karomiru_transfer_v1('30000000-0000-4000-8000-000000001401')->>'current_source_changed','true','current catalog change is reported without rewriting the prepared payload');
select is((select fixed_payload from public.karomiru_transfers where id='30000000-0000-4000-8000-000000001401'),(select fixed_payload from fixed_transfer),'prepared nutrient payload stays immutable');
select is((select (r->>'amount_numerator')::numeric from jsonb_array_elements(public.get_karomiru_source_v1((select request from entry_request))->'nutrients') r where r->>'code'='protein'),10::numeric,'past entry still uses its original nutrient snapshot after catalog edit');
select is((select jsonb_agg(to_jsonb(s) order by s.meal_entry_id,s.nutrient_code) from public.meal_entry_nutrient_snapshots s where s.meal_entry_id=(select (result->>'entry_id')::uuid from transfer_fixtures where kind='entry')),(select data from before_transfer_snapshots),'sharing and catalog edits never rewrite old snapshots');
select throws_ok($$update public.karomiru_transfers set fixed_payload='{}' where id='30000000-0000-4000-8000-000000001401'$$,'PT409','immutable_transfer_payload','fixed payload cannot be overwritten');
select is(public.update_karomiru_transfer_status_v1('30000000-0000-4000-8000-000000001402',2,now(),'30000000-0000-4000-8000-000000001401',1,'confirmed')->>'status','confirmed','only explicit manual confirmation changes status');
select is(public.update_karomiru_transfer_status_v1('30000000-0000-4000-8000-000000001402',2,now(),'30000000-0000-4000-8000-000000001401',1,'confirmed')->>'revision','2','confirmation retry recovers original receipt');
select throws_ok($$select public.update_karomiru_transfer_status_v1(gen_random_uuid(),2,now(),'30000000-0000-4000-8000-000000001401',1,'revoked')$$,'PT409','revision_conflict','stale status revision rejected');
select is(public.update_karomiru_transfer_status_v1(gen_random_uuid(),2,now(),'30000000-0000-4000-8000-000000001401',2,'revoked')->>'status','revoked','manual confirmation can be revoked');
select throws_ok($$select public.update_karomiru_transfer_status_v1(gen_random_uuid(),2,now(),'30000000-0000-4000-8000-000000001401',3,'confirmed')$$,'PT409','transfer_already_revoked','revoked payload requires a new preparation');
select ok(not private.phase8_nutrient_output_compatible('vitamin_a','ug_rae','ug_rae',100,'iu',null),'IU is not treated as RAE');
select ok(not private.phase8_nutrient_output_compatible('vitamin_e','mg','mg',100,'alpha_te',null),'alpha-TE is not silently total alpha-tocopherol');
select ok(not private.phase8_nutrient_output_compatible('folate','ug','ug',100,'dfe',null),'DFE is not silently folate mass');
select ok(not private.phase8_nutrient_output_compatible('carbohydrate','g','g',100,null,'https://world.openfoodfacts.org/product/example'),'ambiguous old OFF C is not a total carbohydrate output');
select ok(not private.phase8_nutrient_output_compatible('selenium','ug','mg',100,null,null),'unit mismatch excluded');
select is(jsonb_array_length(public.export_user_data_v2()->'transfers'),2,'new table is exported immediately');
select is(public.export_user_data_v2()->'definitions'->'standard_nutrient_codes'->>3,'saturated_fat','v2 export standard order matches the UI');
select is(public.export_user_data_v1()->>'schema_version','1','v1 export still available');
select public.upsert_user_profile(0,((now() at time zone 'Asia/Tokyo')::date-interval '30 years')::date,'male',175,60,(now() at time zone 'Asia/Tokyo')::date,'moderate',null,'Asia/Tokyo');
select public.mutate_body_measurement_v1('create',gen_random_uuid(),2,now(),'30000000-0000-4000-8000-000000001420',0,0,null,jsonb_build_object('measured_on',(now() at time zone 'Asia/Tokyo')::date,'weight_kg','62','body_fat_percent',null,'measured_at',null,'time_zone','Asia/Tokyo','source','manual'));
select public.update_body_settings_v1(gen_random_uuid(),2,now(),0,1,jsonb_build_object('weight_sync_mode','latest_measurement','expected_latest_reference',public.get_body_progress_v1()->'latest_reference'));
create temp table linked_auto_goal as select jsonb_build_object('action','set','mode','profile_reference','time_zone',p.time_zone,'effective_from',(now() at time zone p.time_zone)::date,'training_weekdays','[]'::jsonb,'targets',jsonb_build_array(jsonb_build_object('variant','default','energy_kcal',round(private.phase8_profile_energy_raw(p.user_id,(now() at time zone p.time_zone)::date),3)::text,'protein_bps',2500,'fat_bps',2000,'carbohydrate_bps',5500,'fiber_goal_g','20','salt_limit_g','7.5','pfc_tolerance_bps',1000,'energy_tolerance_bps',1000,'calculation_source','profile_reference','calculation_inputs',jsonb_build_object('formula_version','nih-2015-dri2025-v1','profile_revision',p.revision,'birth_date',p.birth_date,'sex',p.sex,'height_cm',p.height_cm::text,'weight_kg',p.weight_kg::text,'activity_level',p.activity_level,'as_of',(now() at time zone p.time_zone)::date,'reference_kcal_raw',private.phase8_profile_energy_raw(p.user_id,(now() at time zone p.time_zone)::date)::text,'adopted_energy_kcal',round(private.phase8_profile_energy_raw(p.user_id,(now() at time zone p.time_zone)::date),3)::text,'weight_measurement_id',p.weight_measurement_id)))) payload from public.user_profiles p where p.user_id=auth.uid();
select throws_ok($$select public.append_nutrition_goal_v1(gen_random_uuid(),2,now(),0,(select jsonb_set(payload,'{targets,0,calculation_inputs,weight_measurement_id}','"88888888-8888-4888-8888-888888888888"') from linked_auto_goal))$$,'PT409','profile_reference_changed','automatic goal cannot claim an unrelated measurement origin');
select lives_ok($$select public.append_nutrition_goal_v1(gen_random_uuid(),2,now(),0,(select payload from linked_auto_goal))$$,'automatic goal retains the real linked measurement ID');
select set_config('test.transfer_catalog_id',(select result->>'item_id' from transfer_fixtures where kind='catalog'),true);
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111402',true);
set local role authenticated;
select is((select count(*)::integer from public.karomiru_transfers),0,'RLS hides another owner sharing payloads');
select is(jsonb_array_length(public.export_user_data_v2()->'transfers'),0,'export isolates sharing history');
select throws_ok($$select public.get_karomiru_transfer_v1('30000000-0000-4000-8000-000000001401')$$,'PT404','transfer_not_found','other owner cannot read a prepared payload');
select throws_ok($$select public.get_karomiru_source_v1(jsonb_build_object('source_kind','catalog','source_id',current_setting('test.transfer_catalog_id')))$$,'PT404','transfer_source_not_found','source helper explicitly checks owner even when the caller knows an ID');
select ok(not has_table_privilege('authenticated','public.karomiru_transfers','INSERT'),'sharing writes require the authenticated receipt API');
reset role;
select ok(not has_function_privilege('anon','public.prepare_karomiru_transfer_v1(uuid,integer,timestamptz,jsonb)','EXECUTE'),'anonymous prepare denied');
select ok(not has_function_privilege('authenticated','private.phase8_karomiru_payload(uuid,jsonb)','EXECUTE'),'owner parameter helper is private');
select set_config('request.jwt.claim.sub','',true);
delete from auth.users where id='11111111-1111-4111-8111-111111111401';
select is((select count(*)::integer from public.karomiru_transfers where user_id='11111111-1111-4111-8111-111111111401'),0,'account deletion cascades sharing payloads');
select * from finish();
rollback;
